import { Link } from "react-router-dom";

export default function Navbar() {
  return (
    <header className="navbar">
      <div className="logo"><img src="https://mywebprovider.com/grolinq/wp-content/uploads/2025/10/logo.png" alt="" /></div>

      <nav>
        <ul>
          <li><Link to="/Home">Home</Link></li>
          <li><Link to="/about">About</Link></li>
          <li><Link to="/cta">How it Works</Link></li>
          <li><Link to="/testimonials">Solutions</Link></li>
          <li><Link to="/testimonials">Contact Us</Link></li>
        </ul>
      </nav>

      <button className="btn btn-primary">Login</button>
    </header>
  );
}
